from typing import Annotated, Any, Literal, Union
from pydantic import BaseModel
from fastapi import FastAPI, Body
from fastapi.dependencies.utils import analyze_param
import inspect

class Pie(BaseModel):
    time_to_cook: int
    num_ingredients: int

class ApplePie(Pie):
    fruit: Literal["apple"] = "apple"

class PumpkinPie(Pie):
    filling: Literal["pumpkin"] = "pumpkin"

def get_discriminator_value(v: Any) -> str:
    if isinstance(v, dict):
        return v.get("fruit", v.get("filling"))
    return getattr(v, "fruit", getattr(v, "filling", None))

# This is the problematic type
Dessert = Annotated[
    Annotated[ApplePie, "apple"] | Annotated[PumpkinPie, "pumpkin"],
    "discriminator",
]

def test_analyze_param():
    # Simulate what FastAPI does in routing
    # analyze_param(param_name, annotation, value, is_path_param)
    # In the example, dessert is a body parameter, so is_path_param=False, value=inspect.Signature.empty
    details = analyze_param(
        param_name="dessert",
        annotation=Dessert,
        value=inspect.Signature.empty,
        is_path_param=False,
    )
    print(f"Field info: {details.field}")
    if details.field is not None:
        print(f"Field info type: {type(details.field)}")
        # We expect it to be a Body parameter
        from fastapi.params import Body as BodyParam
        if isinstance(details.field, BodyParam):
            print("Correctly identified as Body")
        else:
            print(f"Incorrectly identified as {type(details.field)}")
    else:
        print("Field info is None")

if __name__ == "__main__":
    test_analyze_param()

